    private static CompletionStage<Void> configuration(PlatformRuntime p,Path root){try{Path data=p.plugin.getDataFolder().toPath();var props=new Properties();try(var in=Files.newBufferedReader(data.resolve("platform.properties"))){props.load(in);}int old=Integer.parseInt(props.getProperty("autosell.max-quantity"));props.setProperty("autosell.max-quantity",old==32?"64":"32");Path candidate=data.resolve("platform_trial.candidate");try(var out=Files.newBufferedWriter(candidate,StandardOpenOption.CREATE_NEW)){props.store(out,"fixture candidate");}var plan=p.changes.stage("platform.properties",candidate.getFileName().toString(),p::validateCandidate);return p.apply(plan.id(),false).thenRunAsync(()->check(p,p.settings().quantity()!=old,"reviewed_config_candidate_applies_from_one_canonical_file"),p.owner).thenComposeAsync(v->p.apply(plan.id(),true),p.owner).thenRunAsync(()->{check(p,p.settings().quantity()==old,"config_rollback_restores_settings_without_rolling_back_items_or_money");try{Files.delete(candidate);}catch(Exception e){throw new CompletionException(e);}},p.owner);}catch(Exception e){return CompletableFuture.failedFuture(e);}}
